#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST .001
#define TAU 6.283185
#define PI 3.141592
#define S smoothstep
#define T iTime

mat2 Rot(float a) {
    float s=sin(a), c=cos(a);
    return mat2(c, -s, s, c);
}

float sdBox(vec3 p, vec3 s) {
    p = abs(p)-s;
	return length(max(p, 0.))+min(max(p.x, max(p.y, p.z)), 0.);
}

vec2 N(float angle) {
    return vec2(sin(angle), cos(angle));
}

vec2 Koch(vec2 uv) {
    uv.x = abs(uv.x);

    vec3 col = vec3(0);
    float d;

    float angle = 0.;
    vec2 n = N((5./6.)*3.1415);

    uv.y += tan((5./6.)*3.1415)*.5;
   	d = dot(uv-vec2(.5, 0), n);
    uv -= max(0.,d)*n*2.;

    float scale = 1.;

    n = N((2./3.)*3.1415);

    for(int i=0; i<4; i++) {
        uv *= 3.;
        scale *= 3.;
        uv.x -= 1.25;

        uv.x = abs(uv.x);
        uv.x -= .5;
        d = dot(uv, n);
        uv -= min(0.,d)*n*2.;
    }
    uv /= scale;
    return uv;
}

float GetDist(vec3 p) {


    //p.yz *= Rot(iTime*.2);
    //p.xz *= Rot(iTime*.1);

    float d = sdBox(p, vec3(1));

    vec2 xy = Koch(p.xy);
       xy.xy *= Rot(iTime*.4);
    vec2 yz = Koch(p.yz);
    vec2 xz = Koch(p.xz);
     xz.xy *= Rot(iTime*.4);
    d = max(xy.y, max(yz.y, xz.y));




    return d;
}

float RayMarch(vec3 ro, vec3 rd) {
	float dO=0.;

    for(int i=0; i<MAX_STEPS; i++) {
    	vec3 p = ro + rd*dO;
        float dS = GetDist(p);
        dO += dS;
        if(dO>MAX_DIST || abs(dS)<SURF_DIST) break;
    }

    return dO;
}

vec3 GetNormal(vec3 p) {
    vec2 e = vec2(.001, 0);
    vec3 n = GetDist(p) - 
        vec3(GetDist(p-e.xyy), GetDist(p-e.yxy),GetDist(p-e.yyx));

    return normalize(n);
}

vec3 GetRayDir(vec2 uv, vec3 p, vec3 l, float z) {
    vec3 
        f = normalize(l-p),
        r = normalize(cross(vec3(0,1,0), f)),
        u = cross(f,r),
        c = f*z,
        i = c + uv.x*r + uv.y*u;
    return normalize(i);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;
	vec2 m = iMouse.xy/iResolution.xy;

    vec3 ro = vec3(0, 3, -7);


    vec3 rd = GetRayDir(uv, ro, vec3(0,0.,0), 4.);
    vec3 col = vec3(0);

    float d = RayMarch(ro, rd);

    if(d<MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = GetNormal(p);
        vec3 r = reflect(rd, n);

        float dif = dot(n, normalize(vec3(1,2,3)))*.5+.5;
        col = vec3(dif);

        col = n*.8+.8;

    }



    col = pow(col, vec3(.6));	// gamma correction

    fragColor = vec4(col*vec3(0.2,0.4,1.),1.0);
}
